import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  嗯君: z.object({
    金币: z.coerce.number().transform(v => _.clamp(v, 0, 99999)).prefault(0),
    背包: z.record(z.string().describe('物品名'), z.coerce.number().transform(v => _.clamp(v, 1, 99)).describe('数量'))
      .transform(items => {
        const entries = Object.entries(items);
        return entries.length > 20 ? _.fromPairs(entries.slice(0, 20)) : items;
      }).prefault({})
  }).prefault({})
});

$(() => { registerMvuSchema(Schema); });

import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  当前处境: z.object({
    年: z.coerce.number().transform(v => _.clamp(v, 1, 9999)).prefault(1),
    月: z.coerce.number().transform(v => _.clamp(v, 1, 12)).prefault(1),
    日: z.coerce.number().transform(v => _.clamp(v, 1, 31)).prefault(1),
    时段: z.enum(['清晨', '上午', '午后', '傍晚', '夜晚']).prefault('清晨'),
    地点: z.enum(['木屋', '温室', '翡翠之森', '曦风镇街道', '曦风镇市场', '冒险者公会', '邮局', '曦风镇图书馆']).prefault('木屋'),
    天气: z.enum(['晴', '阴', '微雨', '暴雨', '雪', '雾']).prefault('晴')
  }).prefault({})
});

$(() => { registerMvuSchema(Schema); });

