<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>植物学家的观察手账</title>
</head>
<body>
    <style>
        @import url("https://fontsapi.zeoseven.com/871/main/result.css");
        @import url("https://fontsapi.zeoseven.com/815/main/result.css");
        /* --- 1. 核心变量定义：自然大地色系 --- */
        :root {
            --elaine-bg-paper: #f4f1ea; /* 燕麦纸张底色 */
            --elaine-text-main: #4a3f35; /* 深棕色墨迹 */
            --elaine-text-sub: #7a6f65; /* 浅棕色次要文本 */
            --elaine-accent-green: #6b8e23; /* 苔绿色强调 */
            --elaine-accent-gold: #d4af37; /* 琥珀金 */
            --elaine-border-color: rgba(74, 63, 53, 0.3); /* 铅笔描边色 */

            --elaine-font-title: "Z Labs Pixel 12px M CN", cursive;
            --elaine-font-handwriting: 'Comic Sans MS', 'Bradley Hand', 'Segoe Script', cursive, 'KaiTi', '楷体', serif;
            --elaine-font-base: "ChillHuoFangSong", 'Georgia', 'Times New Roman', 'FangSong', '仿宋', serif;

            --elaine-radius-sketch: 255px 15px 225px 15px/15px 225px 15px 255px; /* 模拟手绘不规则边框 */
            --elaine-transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
        }

        /* --- 2. 全局容器与手账质感 --- */
        .stb-elaine-wrapper {
            width: 100%;
            max-width: 500px;
            margin: 15px auto;
            font-family: var(--elaine-font-base);
            color: var(--elaine-text-main);
            /* 纸张纹理背景 */
            background-color: var(--elaine-bg-paper);
            background-image:
                radial-gradient(rgba(0,0,0,0.03) 1px, transparent 1px),
                radial-gradient(rgba(0,0,0,0.03) 1px, transparent 1px);
            background-size: 20px 20px;
            background-position: 0 0, 10px 10px;

            border: 2px solid var(--elaine-border-color);
            border-radius: var(--elaine-radius-sketch);
            box-shadow: 3px 4px 10px rgba(0, 0, 0, 0.08), inset 0 0 20px rgba(107, 142, 35, 0.05);
            overflow: hidden;
        }

        /* --- 3. 折叠交互 (Details & Summary) --- */
        .stb-elaine-details {
            width: 100%;
        }

        .stb-elaine-summary {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: clamp(10px, 3cqw, 15px) clamp(15px, 4cqw, 20px);
            background-color: rgba(107, 142, 35, 0.1);
            border-bottom: 2px dashed var(--elaine-border-color);
            cursor: pointer;
            user-select: none;
            list-style: none;
            font-family: var(--elaine-font-title);
            font-weight: normal;
            font-size: clamp(14px, 4cqw, 16px);
            transition: var(--elaine-transition);
        }

        /* 隐藏默认的三角形 */
        .stb-elaine-summary::-webkit-details-marker {
            display: none;
        }

        .stb-elaine-summary:hover {
            background-color: rgba(107, 142, 35, 0.2);
        }

        .stb-elaine-summary:active {
            transform: scale(0.98);
        }

        .stb-elaine-icon-toggle {
            font-size: 18px;
            transition: transform 0.3s ease;
            color: var(--elaine-accent-green);
        }

        .stb-elaine-details[open] .stb-elaine-icon-toggle {
            transform: rotate(180deg);
        }

        /* --- 4. 主体内容区 --- */
        .stb-elaine-content {
            padding: clamp(15px, 4cqw, 20px);
            display: flex;
            flex-direction: column;
            gap: 20px;
            /* 展开动画 */
            animation: unfold 0.4s ease-out forwards;
            transform-origin: top;
        }

        @keyframes unfold {
            from { opacity: 0; transform: scaleY(0.9); }
            to { opacity: 1; transform: scaleY(1); }
        }

        /* --- 5. 模块标题 --- */
        .stb-elaine-section-title {
            font-family: var(--elaine-font-title);
            font-weight: normal;
            font-size: clamp(15px, 4cqw, 18px);
            color: var(--elaine-accent-green);
            margin: 0 0 10px 0;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .stb-elaine-section-title::after {
            content: '';
            flex-grow: 1;
            height: 1px;
            background: repeating-linear-gradient(to right, var(--elaine-border-color) 0, var(--elaine-border-color) 4px, transparent 4px, transparent 8px);
        }

        /* --- 6. 环境记录 (网格布局) --- */
        .stb-elaine-env-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 120px), 1fr));
            gap: 10px;
        }

        .stb-elaine-env-item {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: clamp(13px, 3.5cqw, 14px);
            padding: 6px 10px;
            border: 1px solid var(--elaine-border-color);
            border-radius: var(--elaine-radius-sketch);
            background: rgba(255, 255, 255, 0.4);
        }

        .stb-elaine-env-icon {
            font-size: 16px;
            opacity: 0.8;
        }

        /* --- 7. 培育观察 --- */
        .stb-elaine-observe-row {
            display: flex;
            justify-content: space-between;
            align-items: baseline;
            margin-bottom: 8px;
            font-size: clamp(13px, 3.5cqw, 15px);
        }

        .stb-elaine-stage-tag {
            background-color: var(--elaine-accent-green);
            color: #fff;
            padding: 2px 8px;
            border-radius: 10px;
            font-family: var(--elaine-font-title);
            font-weight: normal;
            font-size: 12px;
            box-shadow: 1px 2px 4px rgba(0,0,0,0.1);
        }

        /* 手绘风进度条 */
        .stb-elaine-progress-wrapper {
            width: 100%;
            height: 12px;
            border: 2px solid var(--elaine-border-color);
            border-radius: 10px;
            background: rgba(255, 255, 255, 0.5);
            overflow: hidden;
            position: relative;
            margin-bottom: 15px;
        }

        .stb-elaine-progress-bar {
            height: 100%;
            background-color: var(--elaine-accent-green);
            /* 模拟水彩涂抹纹理 */
            background-image: linear-gradient(45deg, rgba(255,255,255,0.2) 25%, transparent 25%, transparent 50%, rgba(255,255,255,0.2) 50%, rgba(255,255,255,0.2) 75%, transparent 75%, transparent);
            background-size: 10px 10px;
            border-radius: 8px;
            transition: width 0.5s ease;
        }

        /* 当日观察便签 */
        .stb-elaine-note {
            font-family: var(--elaine-font-title);
            font-weight: normal;
            font-size: clamp(14px, 4cqw, 15px);
            line-height: 1.6;
            padding: 12px 15px;
            background-color: rgba(255, 255, 255, 0.6);
            border-left: 4px solid var(--elaine-accent-green);
            border-radius: 0 8px 8px 0;
            box-shadow: 2px 2px 5px rgba(0,0,0,0.05);
            position: relative;
        }

        .stb-elaine-note::before {
            content: '"';
            position: absolute;
            top: 5px;
            left: 5px;
            font-size: 24px;
            color: var(--elaine-accent-green);
            opacity: 0.3;
            font-family: serif;
        }

        /* --- 8. 资产与行囊 --- */
        .stb-elaine-inventory-section {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .stb-elaine-gold {
            font-family: var(--elaine-font-title);
            font-size: 15px;
            font-weight: normal;
            color: var(--elaine-text-main);
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .stb-elaine-gold-val {
            color: var(--elaine-accent-gold);
            text-shadow: 1px 1px 0 rgba(0,0,0,0.1);
        }

        .stb-elaine-bag {
            font-size: clamp(12px, 3.5cqw, 14px);
            padding: 10px;
            border: 1px dashed var(--elaine-border-color);
            border-radius: var(--elaine-radius-sketch);
            background: rgba(255, 255, 255, 0.3);
            max-height: 120px;
            overflow-y: auto;
            word-break: break-all;
        }

        /* 自定义滚动条 */
        .stb-elaine-bag::-webkit-scrollbar {
            width: 6px;
        }
        .stb-elaine-bag::-webkit-scrollbar-track {
            background: transparent;
        }
        .stb-elaine-bag::-webkit-scrollbar-thumb {
            background: var(--elaine-border-color);
            border-radius: 3px;
        }

        .stb-elaine-bag:empty::before {
            content: "行囊空空如也...";
            font-family: var(--elaine-font-title);
            color: var(--elaine-text-sub);
            font-style: italic;
        }
    </style>

    <div class="stb-elaine-wrapper">
        <details class="stb-elaine-details">
            <summary class="stb-elaine-summary">
                <span>🌿 植物学家的观察手账</span>
                <span class="stb-elaine-icon-toggle">▼</span>
            </summary>

            <div class="stb-elaine-content">

                <!-- 环境记录 -->
                <div>
                    <h3 class="stb-elaine-section-title">环境记录</h3>
                    <div class="stb-elaine-env-grid">
                        <div class="stb-elaine-env-item">
                            <span class="stb-elaine-env-icon">📅</span>
                            <span>{{format_message_variable::stat_data.当前处境.年}}年{{format_message_variable::stat_data.当前处境.月}}月{{format_message_variable::stat_data.当前处境.日}}日</span>
                        </div>
                        <div class="stb-elaine-env-item">
                            <span class="stb-elaine-env-icon">🕰️</span>
                            <span>{{format_message_variable::stat_data.当前处境.时段}}</span>
                        </div>
                        <div class="stb-elaine-env-item">
                            <span class="stb-elaine-env-icon">📍</span>
                            <span>{{format_message_variable::stat_data.当前处境.地点}}</span>
                        </div>
                        <div class="stb-elaine-env-item">
                            <span class="stb-elaine-env-icon">🌦️</span>
                            <span>{{format_message_variable::stat_data.当前处境.天气}}</span>
                        </div>
                    </div>
                </div>

                <!-- 培育观察 -->
                <div>
                    <h3 class="stb-elaine-section-title">培育观察</h3>
                    <div class="stb-elaine-observe-row">
                        <span>对象：伊莱恩</span>
                        <span class="stb-elaine-stage-tag">{{format_message_variable::stat_data.伊莱恩.成长阶段}}</span>
                    </div>

                    <div class="stb-elaine-observe-row" style="font-size: 12px; color: var(--elaine-text-sub);">
                        <span>依赖值</span>
                        <span>{{format_message_variable::stat_data.伊莱恩.对嗯君情感.依赖值}} / 500+</span>
                    </div>
                    <div class="stb-elaine-progress-wrapper">
                        <!-- 依赖值进度条，假设500为发情期阈值，超过500按100%算 -->
                        <div class="stb-elaine-progress-bar" style="width: calc(min({{format_message_variable::stat_data.伊莱恩.对嗯君情感.依赖值}}, 500) * 0.2%);"></div>
                    </div>

                    <div class="stb-elaine-note">
                        $1
                    </div>
                </div>

                <!-- 行囊 -->
                <div class="stb-elaine-inventory-section">
                    <h3 class="stb-elaine-section-title">行囊</h3>
                    <div class="stb-elaine-gold">
                        <span>研究经费：</span>
                        <span class="stb-elaine-gold-val">{{format_message_variable::stat_data.嗯君.金币}} 🪙</span>
                    </div>
                    <div id="stb-elaine-bag-data" style="display: none;">{{format_message_variable::stat_data.嗯君.背包}}</div>
                    <div class="stb-elaine-bag" id="stb-elaine-bag-view"></div>
                </div>

            </div>
        </details>
    </div>
<script>
(function () {
    const data = document.getElementById('stb-elaine-bag-data');
    const view = document.getElementById('stb-elaine-bag-view');

    if (!data || !view) return;

    const raw = data.textContent.trim();

    if (!raw) {
        view.innerHTML = '';
        return;
    }

    /*
     * format_message_variable 实际输出：
     *
     * 宁静之根委托单: 1 旅行口粮: 1
     *
     * 因此不使用 JSON.parse。
     */

    const regex = /(.+?)[：:]\s*(\d+)(?=\s|$)/g;
    let match;
    let html = '';

    while ((match = regex.exec(raw)) !== null) {
        const item = match[1].trim();
        const count = Number(match[2]);

        if (!item || count <= 0) continue;

        html += `
            <div style="
                display:flex;
                justify-content:space-between;
                margin-bottom:4px;
                border-bottom:1px dashed var(--elaine-border-color);
                padding-bottom:2px;
            ">
                <span>${item}</span>
                <span>x ${count}</span>
            </div>
        `;
    }

    view.innerHTML = html;

})();
</script>
</body>
</html>
