<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>从0开始的异世界植物养成指南</title>
    <style>
        /* 引入指定像素字体 */
        @import url("https://fontsapi.zeoseven.com/689/main/result.css");

        /* =========================================
           Design Tokens (像素风 & 春季配色)
           ========================================= */
        :root {
            /* 色彩系统 */
            --color-bg-base: #fdfbf7;      /* 暖白底色 */
            --color-bg-surface: #f4f7f2;   /* 极浅的抹茶绿背景 (版块容器) */
            --color-bg-card: #ffffff;      /* 纯白卡片 */
            --color-text-main: #5c4d43;    /* 摩卡棕 (主文本) */
            --color-text-muted: #8a7b72;   /* 浅摩卡 (次要文本) */
            --color-primary: #8fbc8f;      /* 抹茶绿 (主色调) */
            --color-primary-hover: #7ab07a;
            --color-accent: #ffb6c1;       /* 浅粉色 (点缀) */
            --color-border: #5c4d43;       /* 像素边框颜色 (同主文本色) */

            /* 排版系统 (双字体策略) */
            --font-pixel: "ChangBanDianSong 12", sans-serif; /* 标题与强调 */
            --font-default: sans-serif;                      /* 大段正文 */

            /* 流式字号 */
            --text-xs: clamp(0.75rem, 2cqw, 0.85rem);
            --text-sm: clamp(0.85rem, 2.5cqw, 0.95rem);
            --text-base: clamp(1rem, 3cqw, 1.1rem);
            --text-lg: clamp(1.1rem, 3.5cqw, 1.3rem);
            --text-xl: clamp(1.4rem, 4cqw, 1.8rem);
            --text-xxl: clamp(1.8rem, 5cqw, 2.5rem);

            /* 间距系统 (流式内外边距) */
            --space-xs: clamp(4px, 1cqw, 8px);
            --space-sm: clamp(8px, 2cqw, 15px);
            --space-md: clamp(15px, 3cqw, 20px);
            --space-lg: clamp(20px, 4cqw, 30px);
            --space-xl: clamp(30px, 6cqw, 50px);

            /* 像素风边框 (利用多重box-shadow模拟) */
            --pixel-border-sm: 
                -2px 0 0 0 var(--color-border),
                2px 0 0 0 var(--color-border),
                0 -2px 0 0 var(--color-border),
                0 2px 0 0 var(--color-border);

            --pixel-border-md: 
                -4px 0 0 0 var(--color-border),
                4px 0 0 0 var(--color-border),
                0 -4px 0 0 var(--color-border),
                0 4px 0 0 var(--color-border),
                -2px -2px 0 0 var(--color-border),
                2px -2px 0 0 var(--color-border),
                -2px 2px 0 0 var(--color-border),
                2px 2px 0 0 var(--color-border);

            /* 像素风阴影 */
            --pixel-shadow: 4px 4px 0 0 rgba(92, 77, 67, 0.15);
            --pixel-shadow-hover: 6px 6px 0 0 rgba(92, 77, 67, 0.25);

            /* 动效 */
            --transition-base: all 0.2s steps(4); /* 阶梯式过渡，增强像素感 */
        }

        /* =========================================
           基础样式重置 & 容器查询
           ========================================= */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            /* 全局默认使用像素字体，大段正文通过类名覆盖 */
            font-family: var(--font-pixel);
            font-weight: normal;
            background-color: var(--color-bg-base);
            color: var(--color-text-main);
            padding: var(--space-md);
            container-type: inline-size;
            word-wrap: break-word;
            overflow-wrap: break-word;
