                if (!container) return;

                if (typeof getChatMessages !== 'function') {
                    container.innerHTML = '<p class="text-default" style="color: var(--color-text-muted);">请在酒馆助手中开启相关API以加载剧情分支。</p>';
                    return;
                }

                try {
                    const messages = getChatMessages("0", { include_swipes: true });
                    if (!messages || messages.length === 0 || !messages[0].swipes || messages[0].swipes.length <= 1) {
                        container.innerHTML = '<p class="text-default" style="color: var(--color-text-muted);">暂无其他培育记录。</p>';
                        return;
                    }

                    const swipes = messages[0].swipes;
                    container.innerHTML = ''; 

                    for (let i = 1; i < swipes.length; i++) {
                        const content = swipes[i];
                        let title = `记录 ${i}`;
                        let description = "点击查看详细记录。";

                        const titleMatch = content.match(/<!--\s*title:\s*(.*?)\s*-->/s);
                        if (titleMatch) title = titleMatch[1].trim();

                        const descMatch = content.match(/<!--\s*desc:\s*(.*?)\s*-->/s);
                        if (descMatch) description = descMatch[1].trim();

                        const item = document.createElement('div');
                        item.className = 'opening-item';
                        item.style.setProperty('--index', i - 1);
                        // 标题使用像素字体(默认继承)，描述使用正文字体
                        item.innerHTML = `<h4>${title}</h4><p class="text-default">${description}</p>`;

                        item.addEventListener('click', async (event) => {
                            event.currentTarget.style.pointerEvents = 'none';
                            try {
                                await setChatMessages([{message_id: 0, swipe_id: i}]);
                            } catch (error) {
                                console.error('切换失败:', error);
                                event.currentTarget.style.pointerEvents = 'auto';
                            }
                        });
                        container.appendChild(item);
                    }
                } catch (error) {
                    console.error('加载失败:', error);
                }
            }

            setTimeout(loadOpenings, 100);
        })();
    </script>
</body>
</html>
